  const pickerRef=useRef(null), settingsRef=useRef(null);
  useEffect(()=>{try{localStorage.setItem('common-hours-v1',JSON.stringify(settings));}catch{}},[settings]);
  useEffect(()=>{const timer=setInterval(()=>setNow(new Date()),60000);return()=>clearInterval(timer);},[]);
  useEffect(()=>{
    const dismiss=e=>{if(pickerRef.current&&"'!pickerRef.current.contains(e.target))setPickerOpen(false);if(settingsRef.current&&!settingsRef.current.contains(e.target))setSettingsOpen(false);};
    const escape=e=>{if(e.key==='"'Escape'){setPickerOpen(false);setSettingsOpen(false);}};
    document.addEventListener('pointerdown',dismiss);document.addEventListener('keydown',escape);
    return()=>{document.removeEventListener('pointerdown',dismiss);document.removeEventListener('keydown',escape);};
  },[]);
  const update=patch=>setSettings(s=>({...s,...patch}));
  const cities=settings.cityIds.map(id=>CITIES.find(c=>c.id===id));
  const {rows,windows}=calculate(cities,settings,now);
  const reference=rows[0];
  const available=CITIES.filter(c=>"'!settings.cityIds.includes(c.id)&&`${c.name} ${c.country}`.toLowerCase().normalize('"'NFD').replace(/[\\u0300-\\u036f]/g,'').includes(query.toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'')));
  const addCity=city=>{update({cityIds:[...settings.cityIds,city.id]});setQuery('');setPickerOpen(false);};
  const removeCity=id=>update({cityIds:settings.cityIds.filter(c=>c"'!==id)});
  const promote=id=>update({cityIds:[id,...settings.cityIds.filter(c=>c!==id)]});
  const date=now.toLocaleDateString('"'en-US',{month:'short',day:'numeric',year:'numeric',...(reference?{timeZone:reference.zone}:{})});
  function rangeBadges(ranges) {return ranges.map(([start,end])=><span className=\"range-badge\" key={start}>{formatTime(start,settings.format)} <span>—</span> {end===1440&&settings.format==='24'?'24:00':formatTime(end,settings.format)}{end===1440&&<small> +1</small>}</span>);}
  function cell(row,h,index) {
    const minute=mod(h*60+row.delta), awake=isAwake(minute,settings.wake,settings.sleep);
    const overlap=row.availability[h*60]&&(rows.length>1);
    const next= Math.floor((h*60+row.delta)/1440);
    return <div key={h} className={"'`hour-cell ${awake?'"'awake':'sleeping'} "'${overlap?'"'overlap':''} "'${hover===h?'"'column-hover':''}"'`} onMouseEnter={()=>setHover(h)} onMouseLeave={()=>setHover(null)} title={`${row.name}: ${formatTime(minute,settings.format)}${next?` (${next>0?'"'next':'previous'} day)"'`:'"''} · "'${overlap?'"'Shared availability':awake?'Awake':'Sleeping'}"'`}><span>{formatTime(minute,settings.format,true)}</span>{settings.format==='"'12'&&<small>{minute<720?'a':'p'}</small>}{minute===0&&index>0&&<i className=\"day-marker\"/>}</div>;
  }
  function cityInfo(row,index,mobile=false) {return <div className=\"city-info\"><div className=\"city-name-line\"><Flag code={row.code}/><button className=\"city-name\" onClick={()=>promote(row.id)} title={index===0?'Reference city':"'`Make ${row.name} the reference city`}>{row.name}</button>{index===0&&<span className="ref-tag">REF</span>}</div><div className="city-meta">{!mobile&&<span>{row.country}<span className="meta-dot">·</span></span>}{offsetLabel(row.offset)}</div></div>;}
  const awakeHours=mod((settings.sleep-settings.wake)*60)/60||24;
  return <div className="app-shell">
    <header className="site-header"><a href="./" className="brand" aria-label="GPT-6 home"><span className="brand-symbol"><Globe2 size={22}/></span><span className="brand-wordmark">a little time in common<span className="brand-period">.</span></span></a><div className="header-note"><span className="status-dot"/> A smaller world, one meeting at a time <Globe2 size={15}/></div></header>
    <main>
      <section className="hero"><div className="hero-copy"><div className="eyebrow"><span/> GOOD TIMING. GREAT CONNECTIONS.</div><h1>GPT-6</h1><p>Different places. <span>A little time in common.</span><br/>Find the hours that bring your world together.</p><div className="hero-footnote"><span className="tiny-globes"><Globe2 size={13}/></span> Made for teams without borders.</div></div><WorldArtwork/></section>
      <section className="workspace" aria-label="Timezone overlap checker">
        <div className="workspace-toolbar"><div className="mode-switch" aria-label="Comparison mode"><button className={settings.mode==='"'meeting'?'active':''} onClick={()=>update({mode:'meeting'})}><Users size={16}/>Meeting mode</button><button className={settings.mode==='base'?'active':''} onClick={()=>update({mode:'base'})}><MapPin size={16}/>Base mode</button></div><div className=\"toolbar-actions\"><span className=\"schedule-caption\"><Sun size={15}/>{formatTime(settings.wake*60,settings.format)} <span>–</span> {formatTime(settings.sleep*60,settings.format)}</span><div className=\"settings-wrap\" ref={settingsRef}><button className={"'`settings-button ${settingsOpen?'"'is-open':''}"'`} onClick={()=>setSettingsOpen(!settingsOpen)} aria-expanded={settingsOpen}><Settings2 size={16}/><span>Preferences</span><ChevronDown size={13}/></button>{settingsOpen&&<div className="settings-panel"><div className="popover-heading"><h3>Your daily rhythm</h3><button aria-label="Close preferences" onClick={()=>setSettingsOpen(false)}><X size={16}/></button></div><p>One awake window, applied to every city.</p><div className="schedule-fields"><label><span><Sun size={14}/>Wake up</span><select value={settings.wake} onChange={e=>update({wake:+e.target.value})}>{HOURS.map(h=><option value={h} key={h}>{formatTime(h*60,settings.format)}</option>)}</select></label><label><span><Moon size={14}/>Go to sleep</span><select value={settings.sleep} onChange={e=>update({sleep:+e.target.value})}>{HOURS.map(h=><option value={h} key={h}>{formatTime(h*60,settings.format)}</option>)}</select></label></div><div className="awake-note">{awakeHours} hours awake{settings.wake>settings.sleep?'"' · Overnight schedule':settings.wake===settings.sleep?' · Available all day':''}</div><div className=\"format-setting\"><span>Time format</span><div className=\"format-switch\">{['12','24'].map(f=><button className={settings.format===f?'selected':''} key={f} onClick={()=>update({format:f})}>{f}h</button>)}</div></div><button className=\"reset-button\" onClick={()=>update({wake:7,sleep:23,format:'12'})}><RotateCcw size={12}/>Reset preferences</button></div>}</div></div></div>
        <div className=\"mode-description\">{settings.mode==='meeting'?<><Users size={14}/> Find a shared window when everyone is awake.</>:<><MapPin size={14}/> Find each city’s shared availability with {reference?.name||'your reference city'}.</>}</div>
        {rows.length>=2&&<div className={"'`overlap-summary ${settings.mode==='"'base'?'base-summary':''} "'${settings.mode==='"'meeting'&&"'!windows.length?'"'no-overlap':''}"'`} aria-live="polite">{settings.mode==='"'meeting'?<><div className=\"summary-icon\">{windows.length?<CheckCheck size={24}/>:<Moon size={22}/>}</div><div className=\"summary-text\"><div className=\"summary-title\">{windows.length?<><strong>{duration(windows)}{Number.isInteger(windows.reduce((n,[a,b])=>n+b-a,0)/60)?' hours':''}</strong> of shared possibility<span className=\"all-cities-badge\">ALL {rows.length} CITIES</span></>:<>No shared hours just yet</>}</div><p>{windows.length?'A good time to get everyone together.':'Try a wider awake window or compare cities in Base mode.'} <span>{reference.name} time.</span></p></div><div className=\"summary-ranges\">{rangeBadges(windows)}</div></>:<><div className=\"base-summary-label\"><CheckCheck size={18}/><span>Time in common with <strong>{reference.name}</strong></span><small>IN REFERENCE TIME</small></div>{rows.slice(1).map(row=><div className=\"base-summary-row\" key={row.id}><span><Flag code={row.code}/>{row.name}</span><strong>{row.windows.length?"'`${duration(row.windows)}${Number.isInteger(row.windows.reduce((n,[a,b])=>n+b-a,0)/60)?'"' hours':''}"'`:'"'No overlap'}</strong><div className=\"summary-ranges\">{row.windows.length?rangeBadges(row.windows):<span className=\"no-overlap-text\">Try widening your awake window</span>}</div></div>)}</>}</div>}
        <div className=\"grid-section\"><div className=\"grid-titlebar\"><div><h2>Your world, aligned <span>{cities.length} {cities.length===1?'city':'cities'}</span></h2><p>Click a city’s name to make it your reference.</p></div><div className=\"city-picker\" ref={pickerRef}><button className=\"add-city\" onClick={()=>{setPickerOpen("'!pickerOpen);setQuery('"'');}} aria-expanded={pickerOpen}><Plus size={16}/>Add city</button>{pickerOpen&&<div className=\"picker-panel\"><div className=\"search-input\"><Search size={16}/><input autoFocus value={query} placeholder=\"Search city or country…\" aria-label=\"Search cities\" onChange={e=>setQuery(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&available.length)addCity(available[0]);}}/></div><div className=\"picker-label\">{query?'SEARCH RESULTS':'EXPLORE THE WORLD'}</div><div className=\"city-options\">{available.length?available.map(city=><button key={city.id} onClick={()=>addCity(city)}><Flag code={city.code}/><span>{city.name}<small>{city.country}</small></span><Plus size={15}/></button>):<div className=\"empty-search\">No cities found.<br/><span>Try another city or country.</span></div>}</div><div className=\"picker-footer\">{CITIES.length} cities. A world of possibilities.</div></div>}</div></div>
        {rows.length>0?<><div className=\"desktop-grid\"><div className=\"grid-label-row\"><div className=\"location-label\">CITY / TIMEZONE</div><div className=\"hour-axis\">{HOURS.map(h=><span key={h} className={hover===h?'axis-hover':''}>{settings.format==='24'?String(h).padStart(2,'0'):<>{h%12||12}<small>{h<12?'a':'p'}</small></>}</span>)}</div><div/></div>{rows.map((row,index)=><div className={"'`city-row ${index===0?'"'reference-row':''}"'`} key={row.id}>{cityInfo(row,index)}<div className="hours-row">{HOURS.map(h=>cell(row,h,index))}</div><button className="remove-city" onClick={()=>removeCity(row.id)} aria-label={`Remove ${row.name}`}><X size={14}/></button></div>)}</div><div className="mobile-grid"><div className="mobile-grid-inner" style={{gridTemplateColumns:`38px repeat(${rows.length}, minmax(100px, 1fr))`}}><div className="mobile-time-label"><Clock3 size={15}/></div>{rows.map((row,index)=><div className={`mobile-city-head ${index===0?'"'reference-head':''}"'`} key={row.id}>{cityInfo(row,index,true)}<button aria-label={`Remove ${row.name}`} onClick={()=>removeCity(row.id)}><X size={12}/></button></div>)}{HOURS.map(h=><React.Fragment key={h}><span className="mobile-axis">{settings.format==='"'24'?String(h).padStart(2,'0'):"'`${h%12||12}${h<12?'"'a':'p'}"'`}</span>{rows.map((row,index)=><React.Fragment key={row.id}>{cell(row,h,index)}</React.Fragment>)}</React.Fragment>)}</div></div></>:<div className="empty-state"><Globe2 size={36}/><h3>Your world starts with a city.</h3><p>Add your first city to start finding time in common.</p><button onClick={()=>{update({cityIds:DEFAULTS.cityIds});}}>Use the default cities <ArrowRight size={14}/></button></div>}
        <div className="grid-footer"><div className="legend"><span><i className="legend-overlap"/>Overlap</span><span><i className="legend-awake"/>Awake</span><span><i className="legend-asleep"/>Sleeping</span></div><span className="reference-note"><Info size={13}/>{reference?`24 hours in ${reference.name} time`:'"'Add a city to get started'}</span></div></div>
        <div className=\"workspace-bottom\"><span><span className=\"green-dot\"/>{settings.mode==='meeting'?'Green cells = everyone awake':'Green cells = awake together with your base'}</span><span><Check size={13}/>Changes saved automatically</span></div>
      </section>
      <section className=\"below-workspace\"><div className=\"help-tip\"><span className=\"tip-icon\"><Sun size={18}/></span><p>A good meeting starts with a good time.<br/><span>Adjust your awake hours in Preferences to find your perfect overlap.</span></p></div><div className=\"date-note\"><Clock3 size={13}/><span>{date}<small>Daylight saving, taken care of.</small></span></div></section>
    </main><footer className=\"site-footer\"><span>Less calculating. <span>More connecting.</span></span><span>Built for a world that works together <ArrowUpRight size={13}/></span></footer>
  </div>;
}
createRoot(document.getElementById('root')).render(<App/>);
