export function calculate(cities, settings, date = new Date()) {
  if(!cities.length) return { rows: [], common: [], windows: [] };
  const offsets=cities.map(c=>offsetMinutes(c.zone,date));
  const rows=cities.map((city,i)=>({ ...city, offset:offsets[i], delta:offsets[i]-offsets[0] }));
  const common=Array.from({length:1440},(_,m)=>rows.every(r=>isAwake(m+r.delta,settings.wake,settings.sleep)));
  rows.forEach(row=> {
