  assert.deepEqual(rows[1].windows, [[420, 480], [960, 1380]]);
  assert.deepEqual(rows[2].windows, [[420, 840], [1320, 1380]]);
  assert.deepEqual(rows[0].windows, [[420, 840], [960, 1380]]);
});

